template.script:
//
(function() {
  var smTeamsData     = [];
  var smSelectedTeam  = null;
  var smPlayerId      = null;
  var smCountdownTimer = null;
  var smTournamentId  = 0;
  var smBreakPaused   = false;
  var smBreakBusy     = false;
  var smAdvanceFn     = null;  // set while sold screen is active
  var smPausedRemaining = 0;
  var smIsMysterySold = false;

  function smDbName() {
    var parts = (window.location.pathname || '').split('/').filter(Boolean);
    return parts.length ? parts[0] : '';
  }

  function smConsoleCall(model, method, args, kwargs) {
    var dbName = smDbName();
    var payload = {
      jsonrpc: '2.0', method: 'call', id: Date.now(),
      params: {
        model: model, method: method,
        args: args || [], kwargs: kwargs || {}
      }
    };
    var url = dbName
      ? ('/' + dbName + '/auction/console_call')
      : '/web/dataset/call_kw';
    return fetch(url, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(payload)
    }).then(function(r) { return r.json(); });
  }

  function smSyncPauseUi() {
    var sold = document.getElementById('smSoldScreen');
    var pauseBtn = document.getElementById('smPauseBtn');
    var label = document.getElementById('smCountdownLabel');
    if (sold) sold.classList.toggle('sm-break-on', smBreakPaused);
    if (pauseBtn) {
      if (smBreakPaused) {
        pauseBtn.innerHTML = '&#9654; Resume';
        pauseBtn.title = 'Resume auction — hide Break Time on projector &amp; live board';
      } else {
        pauseBtn.innerHTML = '&#9208; Pause';
        pauseBtn.title = 'Pause auction — show Break Time on projector &amp; live board';
      }
    }
    if (label && smBreakPaused) {
      label.innerHTML = 'Paused on Break Time — resume when ready';
    }
  }

  function smStopCountdown(freezeBar) {
    if (smCountdownTimer) { clearInterval(smCountdownTimer); smCountdownTimer = null; }
    var bar = document.getElementById('smProgressBar');
    if (freezeBar && bar) {
      var computed = window.getComputedStyle(bar).width;
      bar.style.transition = 'none';
      bar.style.width = computed;
    }
  }

  window.smToggleBreakPause = function() {
    if (!smTournamentId || smBreakBusy) return;
    var wantBreak = !smBreakPaused;
    smBreakBusy = true;
    var pauseBtn = document.getElementById('smPauseBtn');
    if (pauseBtn) pauseBtn.disabled = true;

    if (wantBreak) {
      // Capture remaining seconds from the label if still counting
      var numEl = document.getElementById('smCountdownNum');
      if (numEl) {
        var n = parseInt(numEl.textContent, 10);
        if (!isNaN(n) && n >= 0) smPausedRemaining = n;
      }
      smStopCountdown(true);
    }

    smConsoleCall('auction.tournament', 'action_set_break_time', [[smTournamentId], wantBreak])
      .then(function(res) {
        var err = res && (res.error || (res.result && res.result.error));
        if (err) {
          console.error('[Break Time]', err);
          return;
        }
        smBreakPaused = wantBreak;
        smSyncPauseUi();
        if (!wantBreak) {
          // After resume: keep sold overlay; let operator click Next Player
          if (smIsMysterySold) {
            var countdownLabel = document.getElementById('smCountdownLabel');
            if (countdownLabel) {
              countdownLabel.innerHTML = 'Ready to continue — reveal after celebration';
            }
            var skipBtn = document.getElementById('smSkipBtn');
            if (skipBtn) skipBtn.innerHTML = '&#9654; Continue to Reveal';
          } else {
            var countdownLabel2 = document.getElementById('smCountdownLabel');
            if (countdownLabel2) {
              countdownLabel2.innerHTML = 'Break ended — click <strong>Next Player Now</strong> when ready';
            }
            var bar = document.getElementById('smProgressBar');
            if (bar) { bar.style.transition = 'none'; bar.style.width = '0%'; }
          }
        }
      })
      .catch(function(e) { console.error('[Break Time]', e); })
      .then(function() {
        smBreakBusy = false;
        if (pauseBtn) pauseBtn.disabled = false;
      });
  };

  /* ── Lock Sell / Unsold until the next player is on stage ─────
     After sell or unsold, the same player stays on screen during the
     stamp/celebration. Sell must stay disabled until changeImage /
     smAdvance commits a new player via acCommitPlayerOnStage. */
  window._acAuctionActionsLocked = false;
  var AC_ACTION_BTN_SEL = [
    'button.sell', 'button.lm-btn-sell', 'button.sw-btn-sell', 'button.hud-btn-sell',
    'button.pt-btn-sell', 'button.cr-btn-sell',
    'button.lm-btn-unsold', 'button.sw-btn-unsold', 'button.hud-btn-unsold',
    'button.pt-btn-unsold', 'button.cr-btn-unsold',
    '.auction-single-buttons button'
  ].join(',');

  window.acLockAuctionActions = function() {
    window._acAuctionActionsLocked = true;
    document.querySelectorAll(AC_ACTION_BTN_SEL).forEach(function(btn) {
      // Keep Next Player enabled — only lock sell / unsold
      var label = (btn.textContent || '').toLowerCase();
      if (label.indexOf('next player') !== -1) return;
      btn.disabled = true;
      btn.setAttribute('data-ac-action-locked', '1');
    });
  };

  window.acUnlockAuctionActions = function() {
    window._acAuctionActionsLocked = false;
    // Fresh zone HTML already has enabled buttons; clear any leftovers
    document.querySelectorAll('[data-ac-action-locked="1"]').forEach(function(btn) {
      btn.disabled = false;
      btn.removeAttribute('data-ac-action-locked');
    });
  };

  // Capture-phase guard so onclick handlers cannot fire while locked
  document.addEventListener('click', function(ev) {
    if (!window._acAuctionActionsLocked) return;
    var t = ev.target && ev.target.closest ? ev.target.closest(AC_ACTION_BTN_SEL) : null;
    if (!t) return;
    var label = (t.textContent || '').toLowerCase();
    if (label.indexOf('next player') !== -1) return;
    ev.preventDefault();
    ev.stopPropagation();
  }, true);

  // Themes define setPlayerUnsold in an earlier script — wrap after load
  if (typeof window.setPlayerUnsold === 'function' && !window.setPlayerUnsold._acWrapped) {
    var _acOrigUnsold = window.setPlayerUnsold;
    window.setPlayerUnsold = function() {
      if (window._acAuctionActionsLocked) return;
      return _acOrigUnsold.apply(this, arguments);
    };
    window.setPlayerUnsold._acWrapped = true;
  }

  // Lock after a successful action_unsold (themes call fetch directly)
  (function() {
    var _fetch = window.fetch;
    if (!_fetch || _fetch._acAuctionWrapped) return;
    function wrappedFetch(url, opts) {
      var body = opts && opts.body;
      var isUnsold = typeof body === 'string' && body.indexOf('action_unsold') !== -1;
      var p = _fetch.apply(this, arguments);
      if (!isUnsold) return p;
      return p.then(function(resp) {
        try {
          var clone = resp.clone();
          clone.json().then(function(data) {
            if (data && !data.error) window.acLockAuctionActions();
          }).catch(function() {});
        } catch (e) {}
        return resp;
      });
    }
    wrappedFetch._acAuctionWrapped = true;
    window.fetch = wrappedFetch;
  })();

  /* Commit on-stage player for the projector after preview prefetch / countdown. */
  window.acCommitPlayerOnStage = function(playerId) {
    playerId = parseInt(playerId || '0', 10);
    if (!playerId) return Promise.resolve();
    // New player on stage → Sell / Unsold are available again
    window.acUnlockAuctionActions();
    return smConsoleCall('auction.team.player', 'action_set_on_stage', [[playerId]])
      .catch(function() { /* projector will catch up on next real navigation */ });
  };

  /* ── Open / Close ──────────────────────────────────────────── */
  window.openSellModal = function() {
    if (window._acAuctionActionsLocked) return;
    smPlayerId     = parseInt(document.body.getAttribute('data-player-id'));
    smSelectedTeam = null;
    smTeamsData    = [];
    if (smCountdownTimer) { clearInterval(smCountdownTimer); smCountdownTimer = null; }
    smBreakPaused = false;
    smAdvanceFn = null;
    var soldScreen = document.getElementById('smSoldScreen');
    if (soldScreen) soldScreen.classList.remove('sm-break-on');
    smSyncPauseUi();

    var isMysteryHidden = ((document.body.getAttribute('data-is-mystery') === '1') || !!window.AUCTION_IS_MYSTERY)
      && !window.AUCTION_MYSTERY_REVEALED;

    // Sync player photo + info to whoever is currently on screen
    var smAvatar = document.getElementById('smPlayerAvatar');
    if (smAvatar) {
      if (isMysteryHidden) {
        smAvatar.removeAttribute('src');
        smAvatar.alt = 'Mystery Player';
        smAvatar.style.visibility = 'hidden';
      } else {
        smAvatar.style.visibility = '';
        smAvatar.src = '/web/image/auction.team.player/' + smPlayerId + '/photo';
      }
    }
    var zone = document.querySelector('[data-player-zone]');
    var modalName = document.getElementById('smPlayerName');
    var modalRole = document.getElementById('smPlayerRole');
    if (isMysteryHidden) {
      if (modalName) modalName.textContent = 'Mystery Player';
      if (modalRole) modalRole.textContent = '?';
    } else if (zone) {
      var nameEl  = zone.querySelector('[data-sm-name]');
      var roleEl  = zone.querySelector('[data-sm-role]');
      if (nameEl  && modalName) modalName.textContent = nameEl.textContent.trim();
      if (roleEl  && modalRole) modalRole.textContent = roleEl.textContent.trim();
    }

    // Show form, hide sold screen
    document.getElementById('smFormPanel').style.display = 'flex';
    document.getElementById('smSoldScreen').classList.remove('visible');

    // Reset form
    document.getElementById('smTeamBadges').innerHTML = '<span class="sm-no-teams">Loading teams\u2026</span>';
    document.getElementById('smTeamPlaceholder').style.display = 'flex';
    document.getElementById('smTeamLogo').style.display = 'none';
    document.getElementById('smTeamNameLabel').style.display = 'none';
    document.getElementById('teamDetailsStrip').style.display = 'none';
    document.getElementById('sellSuggestion').style.display = 'none';
    document.getElementById('sellError').style.display = 'none';
    document.getElementById('smBtnSell').disabled = true;
    document.getElementById('smBtnSell').textContent = 'Sell Player';
    document.getElementById('sellPoints').value = 0;
    document.getElementById('sellModal').classList.add('open');
    smLoadTeams(smPlayerId);
  };

  window.closeSellModal = function() {
    if (smCountdownTimer) { clearInterval(smCountdownTimer); smCountdownTimer = null; }
    document.getElementById('sellModal').classList.remove('open');
  };

  window.smSkipToNext = function() {
    if (smBreakPaused) return;
    if (smCountdownTimer) { clearInterval(smCountdownTimer); smCountdownTimer = null; }
    smAdvanceFn = null;
    document.getElementById('sellModal').classList.remove('open');
    document.getElementById('smSoldScreen').classList.remove('visible');
    document.getElementById('smSoldScreen').classList.remove('sm-break-on');
    document.getElementById('smFormPanel').style.display = 'flex';
    // Mystery players stay on stage until revealed — do not advance yet.
    var isMystery = (document.body.getAttribute('data-is-mystery') === '1')
      || !!window.AUCTION_IS_MYSTERY;
    if (isMystery && !window.AUCTION_MYSTERY_REVEALED && typeof window.acMysteryMarkSold === 'function') {
      window.AUCTION_IS_MYSTERY = true;
      window.acMysteryMarkSold(window._acMysteryPendingSold || null);
      window._acMysteryPendingSold = null;
      return;
    }
    if (typeof changeImage === 'function') { changeImage(true); } else { window.location.reload(); }
  };

  /* ── Load teams ─────────────────────────────────────────────── */
  function smLoadTeams(playerId) {
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        jsonrpc: '2.0', method: 'call',
        params: { model: 'auction.team.player', method: 'get_sell_teams_data', args: [playerId], kwargs: {} }
      })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.error) { smShowError('Failed to load teams. Please try again.'); return; }
      smTeamsData = data.result || [];
      smRenderBadges(smTeamsData);
    })
    .catch(function() { smShowError('Network error loading teams.'); });
  }

  function smRenderBadges(teams) {
    var container = document.getElementById('smTeamBadges');
    if (!teams.length) {
      container.innerHTML = '<span class="sm-no-teams">No teams available</span>';
      return;
    }
    container.innerHTML = '';
    teams.forEach(function(team) {
      var btn = document.createElement('button');
      var disabled = !team.tier_slots_ok || !team.budget_ok;
      btn.className = 'sm-badge' + (disabled ? ' tier-full' : '');
      btn.textContent = team.team_name;
      btn.dataset.teamId = team.team_id;
      if (!team.tier_slots_ok) {
        btn.title = 'Tier slot full for this team';
        btn.disabled = true;
      } else if (!team.budget_ok) {
        btn.title = 'Insufficient budget \u2014 cannot meet this tier\u2019s minimum bid';
        btn.disabled = true;
      } else {
        btn.onclick = function() { smSelectTeam(team); };
      }
      container.appendChild(btn);
    });
  }

  /* ── Select team ─────────────────────────────────────────────── */
  function smSelectTeam(team) {
    smSelectedTeam = team;
    document.querySelectorAll('.sm-badge').forEach(function(b) {
      b.classList.toggle('active', b.dataset.teamId == team.team_id);
    });
    var logo = document.getElementById('smTeamLogo');
    logo.src = '/web/image/auction.team/' + team.team_id + '/logo';
    logo.style.display = 'block';
    document.getElementById('smTeamPlaceholder').style.display = 'none';
    var lbl = document.getElementById('smTeamNameLabel');
    lbl.textContent = team.team_name; lbl.style.display = 'block';

    document.getElementById('smRemainingPts').textContent     = team.remaining_points;
    document.getElementById('smRemainingPlayers').textContent = team.remaining_players;
    document.getElementById('smMaxCall').textContent          = team.max_call;
    document.getElementById('teamDetailsStrip').style.display = 'flex';

    var sug = document.getElementById('sellSuggestion');
    sug.innerHTML = team.remaining_players > 1
      ? '\u2139 Max bid <strong>' + team.max_call + ' pts</strong> &#160;|&#160; Base for remaining: <strong>' + team.effective_base_point + ' pts</strong>'
      : '\u2139 Last player slot! Max bid: <strong>' + team.max_call + ' pts</strong>';
    sug.style.display = 'block';

    var input = document.getElementById('sellPoints');
    input.value = team.effective_base_point;
    input.min   = team.effective_base_point;
    input.max   = team.max_call;
    smClearPresetActive();
    document.getElementById('smBtnSell').disabled = false;
    smHideError();
  }

  /* ── Adjust points ───────────────────────────────────────────── */
  window.smAdjustPoints = function(dir) {
    if (!smSelectedTeam) return;
    var input   = document.getElementById('sellPoints');
    var current = parseInt(input.value) || smSelectedTeam.effective_base_point;
    var inc     = smGetIncrement(current, smSelectedTeam.slabs);
    var next    = Math.min(Math.max(current + dir * inc, smSelectedTeam.effective_base_point), smSelectedTeam.max_call);
    input.value = next;
    smClearPresetActive();
    smHideError();
  };

  /* ── Set preset point value ──────────────────────────────────── */
  window.smSetPoints = function(val, btn) {
    var input = document.getElementById('sellPoints');
    input.value = val;
    // Highlight active preset button
    smClearPresetActive();
    if (btn) btn.classList.add('sm-preset-active');
    smHideError();
  };

  function smClearPresetActive() {
    var btns = document.querySelectorAll('.sm-preset-btn');
    for (var i = 0; i < btns.length; i++) btns[i].classList.remove('sm-preset-active');
  }

  function smGetIncrement(amount, slabs) {
    if (!slabs || !slabs.length) return 50;
    for (var i = 0; i < slabs.length; i++) {
      var s = slabs[i];
      if (amount >= s.from_amount && amount < s.to_amount) return s.increment;
    }
    return slabs[slabs.length - 1].increment || 50;
  }

  /* ── Submit sell ─────────────────────────────────────────────── */
  window.smSubmitSell = function() {
    if (!smSelectedTeam || !smPlayerId) return;
    var finalPoint = parseInt(document.getElementById('sellPoints').value);
    if (isNaN(finalPoint) || finalPoint <= 0) { smShowError('Please enter a valid points value.'); return; }

    var btn = document.getElementById('smBtnSell');
    btn.disabled = true; btn.textContent = 'Selling\u2026';
    smHideError();

    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        jsonrpc: '2.0', method: 'call',
        params: {
          model: 'auction.team.player', method: 'action_sell_from_web',
          args: [smPlayerId, smSelectedTeam.team_id, finalPoint], kwargs: {}
        }
      })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.error) {
        var msg = data.error.data ? data.error.data.message : data.error.message;
        smShowError('Error: ' + msg);
        btn.disabled = false; btn.textContent = 'Sell Player'; return;
      }
      var result = data.result;
      if (!result.success) {
        smShowError(result.error);
        btn.disabled = false; btn.textContent = 'Sell Player'; return;
      }
      smShowSoldScreen(result);
    })
    .catch(function() {
      smShowError('Network error. Please try again.');
      btn.disabled = false; btn.textContent = 'Sell Player';
    });
  };

  /* ── Sold celebration screen ─────────────────────────────────── */
  function smShowSoldScreen(result) {
    // Player is sold — disable Sell / Unsold until next player loads
    if (typeof window.acLockAuctionActions === 'function') {
      window.acLockAuctionActions();
    }
    // Hide form, show sold screen
    document.getElementById('smFormPanel').style.display = 'none';
    var soldScreen = document.getElementById('smSoldScreen');
    var isMystery = ((document.body.getAttribute('data-is-mystery') === '1') || !!window.AUCTION_IS_MYSTERY)
      && !window.AUCTION_MYSTERY_REVEALED;
    if (isMystery) window.AUCTION_IS_MYSTERY = true;
    smIsMysterySold = !!isMystery;
    smBreakPaused = false;
    smPausedRemaining = 0;
    smTournamentId = parseInt(result.tournament_id || 0, 10) || 0;
    soldScreen.classList.remove('sm-break-on');
    smSyncPauseUi();

    // Keep sold details for mystery reveal stamp
    window._acMysteryPendingSold = {
      team_id: result.team_id,
      team_name: result.team_name,
      final_point: result.final_point
    };

    // Fill in data
    var soldPhoto = document.getElementById('smSoldPhoto');
    if (isMystery) {
      soldPhoto.removeAttribute('src');
      soldPhoto.alt = 'Mystery Player';
      soldPhoto.style.visibility = 'hidden';
    } else {
      soldPhoto.style.visibility = '';
      soldPhoto.src = '/web/image/auction.team.player/' + result.player_id + '/photo';
    }
    document.getElementById('smSoldTeamLogo').src  = '/web/image/auction.team/' + result.team_id + '/logo';
    document.getElementById('smSoldTeamName').textContent = result.team_name;
    document.getElementById('smSoldPoints').textContent   = result.final_point;

    // Re-trigger stamp animation by cloning the stamp element
    var oldStamp = document.querySelector('.sm-sold-stamp');
    var newStamp = oldStamp.cloneNode(true);
    oldStamp.parentNode.replaceChild(newStamp, oldStamp);

    soldScreen.classList.add('visible');

    var countdownLabel = document.getElementById('smCountdownLabel');
    var skipBtn = document.getElementById('smSkipBtn');
    if (isMystery) {
      if (countdownLabel) {
        countdownLabel.innerHTML = 'Stay on this player — reveal after celebration (<strong id="smCountdownNum">5</strong>s)';
      }
      if (skipBtn) skipBtn.innerHTML = '&#9654; Continue to Reveal';
    } else {
      if (countdownLabel) {
        countdownLabel.innerHTML = 'Next player in <strong id="smCountdownNum">5</strong> seconds';
      }
      if (skipBtn) skipBtn.innerHTML = '&#9654; Next Player Now';
    }

    // ── Pre-fetch the next player HTML in the background while countdown runs.
    // On cloud the fetch takes 300-800ms; doing it during the 5-second sold
    // animation means the HTML is ready the instant the countdown hits zero.
    // Skipped for mystery — we remain on the same player until reveal.
    var _preFetchedHtml = null;
    var _preFetchDone   = false;
    var _preFetchId     = document.body.getAttribute('data-player-id');
    if (!isMystery && _preFetchId) {
      var _prefetchUrl = window.location.href.split('?')[0] + '?exclude=' + _preFetchId + '&preview=1';
      fetch(_prefetchUrl, { cache: 'no-store' })
        .then(function(r) { return r.ok ? r.text() : null; })
        .then(function(html) { _preFetchedHtml = html; _preFetchDone = true; })
        .catch(function()    { _preFetchDone = true; });
    } else {
      _preFetchDone = true;
    }

    // Advance to the next player using the pre-fetched HTML when available,
    // otherwise fall back to calling changeImage() which will re-fetch.
    function smAdvance() {
      if (smBreakPaused) return;
      smAdvanceFn = null;
      var stillMystery = ((document.body.getAttribute('data-is-mystery') === '1') || !!window.AUCTION_IS_MYSTERY)
        && !window.AUCTION_MYSTERY_REVEALED;
      if (stillMystery && typeof window.acMysteryMarkSold === 'function') {
        window.AUCTION_IS_MYSTERY = true;
        window.acMysteryMarkSold(window._acMysteryPendingSold || {
          team_id: result.team_id,
          team_name: result.team_name,
          final_point: result.final_point
        });
        window._acMysteryPendingSold = null;
        return;
      }
      if (_preFetchedHtml) {
        var parser     = new DOMParser();
        var newDoc     = parser.parseFromString(_preFetchedHtml, 'text/html');
        var newId      = newDoc.body ? newDoc.body.getAttribute('data-player-id') : null;
        var zone       = document.querySelector('[data-player-zone]');
        var newZone    = newDoc.querySelector('[data-player-zone]');
        if (newId && newId !== _preFetchId && zone && newZone) {
          document.body.setAttribute('data-player-id', newId);
          var mysteryFlag = newDoc.body.getAttribute('data-is-mystery') || '0';
          document.body.setAttribute('data-is-mystery', mysteryFlag);
          document.body.removeAttribute('data-mystery-revealed');
          zone.innerHTML = newZone.innerHTML;
          if (typeof window.acMysteryApplyFromBody === 'function') {
            window.acMysteryApplyFromBody();
          } else if (typeof window.acMysterySyncFromZone === 'function') {
            window.acMysterySyncFromZone(newZone);
          }
          if (typeof window.acCommitPlayerOnStage === 'function') {
            window.acCommitPlayerOnStage(newId);
          }
          return;
        }
      }
      // Fallback: pre-fetch failed or same player — let changeImage handle it
      if (typeof changeImage === 'function') { changeImage(true); }
      else { window.location.reload(); }
    }
    smAdvanceFn = smAdvance;

    // Countdown
    var totalSecs = (result.display_seconds && result.display_seconds > 0) ? result.display_seconds : 5;
    var remaining = totalSecs;
    var bar = document.getElementById('smProgressBar');
    bar.style.transition = 'none';
    bar.style.width = '100%';
    document.getElementById('smCountdownNum').textContent = remaining;

    // Force reflow then start shrinking
    bar.offsetWidth;
    bar.style.transition = 'width ' + totalSecs + 's linear';
    bar.style.width = '0%';

    if (smCountdownTimer) { clearInterval(smCountdownTimer); smCountdownTimer = null; }
    smCountdownTimer = setInterval(function() {
      if (smBreakPaused) return;
      remaining -= 1;
      var numEl = document.getElementById('smCountdownNum');
      if (numEl) numEl.textContent = remaining;
      if (remaining <= 0) {
        clearInterval(smCountdownTimer);
        smCountdownTimer = null;
        if (smBreakPaused) return;
        document.getElementById('sellModal').classList.remove('open');
        document.getElementById('smSoldScreen').classList.remove('visible');
        document.getElementById('smFormPanel').style.display = 'flex';
        // If pre-fetch is still in-flight, wait for it (adds at most a few ms
        // on cloud since it started seconds ago); otherwise advance immediately.
        if (_preFetchDone) {
          smAdvance();
        } else {
          var _waitId = setInterval(function() {
            if (smBreakPaused) { clearInterval(_waitId); return; }
            if (_preFetchDone) { clearInterval(_waitId); smAdvance(); }
          }, 50);
        }
      }
    }, 1000);
  }

  function smShowError(msg) { var el = document.getElementById('sellError'); el.textContent = msg; el.style.display = 'block'; }
  function smHideError()    { document.getElementById('sellError').style.display = 'none'; }

  // Close on overlay click (only on form panel, not during sold screen)
  document.getElementById('sellModal').addEventListener('click', function(e) {
    if (e.target === this && document.getElementById('smFormPanel').style.display !== 'none') closeSellModal();
  });

  // ── Auto-advance when auctioneer console finalises a sale ─────────────
  // The auctioneer console sets 'auction:player_sold' in localStorage after
  // a successful finalization. The storage event fires in all other same-
  // origin tabs/windows, triggering changeImage() to load the next player.
  window.addEventListener('storage', function (e) {
    if (e.key === 'auction:player_sold' && e.newValue) {
      try {
        // Mystery players must stay on stage until revealed.
        if (window.AUCTION_IS_MYSTERY && !window.AUCTION_MYSTERY_REVEALED) {
          if (typeof window.acMysteryMarkSold === 'function') {
            window.acMysteryMarkSold(window._acMysteryPendingSold || null);
          }
          return;
        }
        // Give the server a brief moment to commit the state change
        setTimeout(function () {
          if (typeof changeImage === 'function') {
            changeImage(true);
          } else {
            window.location.reload();
          }
        }, 600);
      } catch (err) { /* ignore */ }
    }
  });
})();
//
